import { notification } from "./main.js";
import { NotificationManager } from "./NotificationManager.js";
import { OnBoardingManager } from "./OnBoardingManager.js";
import { PaymentManager } from "./PaymentManager.js";
import dotenv from "dotenv";
dotenv.config();

export const APP_CONFIG = {
  serverBaseUrl: process.env.serverUrl
};




export const CONFIG_SERVERS = {
  base: `${APP_CONFIG.serverBaseUrl}/jsons/base.json`,
  notification: `${APP_CONFIG.serverBaseUrl}/jsons/notification.json`,
  payment: `${APP_CONFIG.serverBaseUrl}/jsons/payment.json`,
  onboarding: `${APP_CONFIG.serverBaseUrl}/jsons/onboarding.json`,
};

const onBoarding = new OnBoardingManager();
const Notification = new NotificationManager();
const payment = new PaymentManager();

export const CONTENT_SYNC_FUNCTIONS = {
  notification: () => Notification.syncNotificationContent(),
  payment: () => payment.syncPaymentContent(),
  onboarding: () => onBoarding.syncOnboardingContent(),
};
